"""Create the Russian prototype handover PDF; uses installed Windows Arial."""
from pathlib import Path
from reportlab.pdfgen import canvas
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, PageBreak
from reportlab.lib import colors
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont
from reportlab.lib.enums import TA_LEFT
root=Path(__file__).resolve().parents[1]
pdfmetrics.registerFont(TTFont('Text','C:/Windows/Fonts/arial.ttf'))
pdfmetrics.registerFont(TTFont('Bold','C:/Windows/Fonts/arialbd.ttf'))
pdfmetrics.registerFontFamily('Text',normal='Text',bold='Bold')
out=root/'output'/'docs';out.mkdir(parents=True,exist_ok=True)
styles=getSampleStyleSheet()
styles.add(ParagraphStyle(name='BodyRU',fontName='Text',fontSize=10,leading=15,spaceAfter=9,textColor=colors.HexColor('#293A3C')))
styles.add(ParagraphStyle(name='TitleRU',fontName='Bold',fontSize=26,leading=31,spaceAfter=18,textColor=colors.HexColor('#24705A')))
styles.add(ParagraphStyle(name='HeadingRU',fontName='Bold',fontSize=15,leading=20,spaceBefore=12,spaceAfter=8,textColor=colors.HexColor('#24705A')))
styles.add(ParagraphStyle(name='SmallRU',fontName='Text',fontSize=8,leading=12,spaceAfter=6))
story=[]
def p(text):story.append(Paragraph(text,styles['BodyRU']))
def h(text):story.append(Paragraph(text,styles['HeadingRU']))
def title(text):story.append(Paragraph(text,styles['TitleRU']))
def table(rows,widths):
    t=Table([[Paragraph(str(v),styles['SmallRU']) for v in r] for r in rows],colWidths=widths,repeatRows=1,hAlign='LEFT')
    t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#E6EDDF')),('VALIGN',(0,0),(-1,-1),'TOP'),('BOTTOMPADDING',(0,0),(-1,-1),8),('TOPPADDING',(0,0),(-1,-1),8),('LINEBELOW',(0,0),(-1,-1),.4,colors.HexColor('#DDDDCC'))]))
    story.append(t)
def page():story.append(PageBreak())
title('Город Хвостиков')
p('Первая версия мобильной игры • 0.1.0 (1) • Android 8.0+<br/>Документ передачи прототипа / 26 сентября 2026')
h('Питомец и его мечта')
p('Ребёнок выбирает питомца, придумывает игровое имя и помогает накопить на велосипед. Он получает ограниченный бюджет, покупает необходимое, выбирает приятные вещи и пополняет копилку. Пять первых периодов знакомят с основами финансовых решений. Если накоплений не хватает, периоды продолжаются.')
p('Когда мечта исполнена, показывается финал. История остаётся в альбоме. Другой питомец начинает с отдельными монетками и покупками; альбом и изученные понятия сохраняются. Следующие мечты: компьютер и набор художника.')
h('Что входит в прототип')
p('5 видов питомцев и 3 окраса; 8 товаров; 6 упражнений по 3 темам; 7 справочных карточек; 3 стадии развития; 3 цели; план и факт; журнал операций; отдельный демо-профиль; взрослый раздел с удалением локальных данных.')
h('Архитектура')
table([['Компонент','Назначение'],['game.dart','Правила экономики, задания, рост, этапы истории. Не зависит от Flutter.'],['store.dart','Riverpod, два профиля Hive, JSON-снимки и резервная копия.'],['main.dart / screens.dart / widgets.dart','Навигация, экраны, формы, подтверждения и обратная связь.'],['pet_scene.dart','Оригинальные иллюстрации, эмоции и движение средствами Flutter.'],['assets/data/content.json','Товары, цели, задания, расписание и теоретические карточки.']],[160,345])
page()
title('Монетки и обучение')
h('Правила экономики')
p('Доход: 120 монеток в начале недели. За завершённое упражнение: 10 однократно на пару «неделя / задание». Необходимый набор: корм 30 + вода 10 + уход 10. Желаемые предметы стоят 20-60. Велосипед стоит 200.')
p('План не перемещает деньги. Покупка уменьшает кошелёк; перевод в копилку уменьшает кошелёк и увеличивает накопления. Снятие выполняет обратное действие после отдельного подтверждения. Факт «Коплю» равен пополнениям минус снятиям за неделю. Отрицательные суммы и недостаток денег блокируются с объяснением.')
p('Пример: 120 дохода + 10 за практику - 50 необходимое - 30 мяч - 40 в копилку = 10 свободных монеток. Свободные деньги переносятся на следующую неделю.')
h('Учебный путь')
table([['Неделя','Навык и практика'],['1','План: распределение между нужным, желаемым и накоплениями.'],['2','Корзина в пределах бюджета; сравнение цен одинаковых товаров.'],['3','Скидка и выбор между покупкой сейчас и приближением мечты.'],['4','Неожиданный ремонт рюкзака, резерв и пересмотр плана.'],['5 и далее','Самостоятельное планирование и повторение практики.']],[75,430])
h('Рост и безопасная ошибка')
p('До 3 очков роста за период: необходимый набор куплен; покупки уложились в план по двум расходным категориям; чистое пополнение копилки положительно. Стадии: 0-3, 4-8, от 9 очков. Результат объясняется в итогах. На второй стадии появляется шарф, на третьей медаль.')
p('После неудачной практики ребёнок получает объяснение и может изменить ответ. При нехватке монеток можно перенести покупку, использовать копилку или однократно получить поддержку совёнка. Питомец не умирает, не заболевает и не теряет достигнутую стадию.')
page()
title('Проверка требований')
p('Основание: техническое задание Департамента финансов Москвы, 2026. Статусы функциональности не заменяют проверку APK на физическом телефоне.')
table([['Требование','Реализация'],['Первый запуск, профиль, внешность','Гостевой режим; 15 комбинаций; игровое имя; повторные подсказки.'],['Бюджет и покупки','Три категории; ограничение суммы; остаток; подтверждения; план/факт и история.'],['Цель и накопления','Велосипед в первой истории, ещё две цели в следующих; отдельная копилка; подтверждение снятия.'],['Задания и теория','6 заданий, 3 темы, 3 типа взаимодействия; объяснения обоих исходов; справочник.'],['Состояние и рост','Настроение после действий; 3 стадии по совокупности решений.'],['Хранение и демо','Локальные снимки Hive и резервная копия; отдельный сбрасываемый тестовый профиль.'],['Взрослый раздел','Барьер случайного входа, темы, общий прогресс, удаление данных, отключение анимаций.'],['Расширение контента','Новые задания существующего типа добавляются в JSON; расписание также в JSON.'],['Доступность','Портрет, 360 dp, увеличенный шрифт, подписи, кнопки 48 dp; звуки не используются.']],[165,340])
h('Проверки и оставшиеся ограничения')
p('В репозитории есть тесты расчётов, повторных операций, сценария пяти недель, продолжения, финала, новой истории, сохранения и изоляции демо. Проверены виджеты при 360 dp и масштабе текста 150%; снимки экранов получены из реального Flutter-интерфейса.')
p('Физический телефон не подключён: установка, холодный запуск до 5 секунд, отклик до 1 секунды и ручной прогон ещё не подтверждены. Карта пока состоит из карточек мест; парк и мастерская используют общий экран. Большие коллекции костюмов, сезоны и музыка отложены.')
page()
title('Установка и демонстрация')
h('На телефоне')
p('Передайте файл «Город-Хвостиков-0.1.apk» на Android 8.0 или новее. Откройте его и разрешите установку для приложения, которым открываете APK. Для самой игры интернет не нужен.')
h('Сквозной сценарий')
for t in ['Выбрать питомца, цвет и игровое имя. Получить 120 монеток.', 'Составить план 50 / 30 / 40. Пройти практику сначала с ошибкой, затем исправить решение.', 'Купить корм, воду, уход и мяч. Попробовать купить ракету при нехватке денег.', 'Отложить 40, посмотреть последствия снятия и отменить его. Подвести итоги недели.', 'Пройти следующие недели, сравнить цены, обсудить скидку и ремонт. Увидеть рост и новую награду.', 'Накопить 200, подтвердить велосипед, увидеть финал и альбом. Начать историю другого питомца.', 'Полностью закрыть и открыть приложение; проверить сохранение. Во взрослом разделе сбросить демо и убедиться, что обычная игра сохранена.']:
 p('• '+t)
h('Для разработчика и организатора')
p('Команды: flutter pub get; flutter analyze; flutter test; flutter build apk --release. На этом компьютере доступен tools/build.ps1. Ключ подписи исключён из Git. Конфигурация описана в README и android/key.properties.example. Точные версии инструментов: docs/build-environment.txt.')
p('Нет сервера, регистрации, рекламы, платежей, аналитики и опасных разрешений Android. Данные профиля находятся на устройстве; резервное копирование Android отключено. Лицензии библиотек доступны во взрослом разделе; шрифт Nunito распространяется по OFL. Иллюстрации оригинальные, нарисованы кодом.')
p('Для финальной конкурсной сдачи ещё потребуются презентация, резервное видео до 3 минут, отчёт физического устройства и доступ экспертов к репозиторию. Черновик карточки RuStore, карта требований и подробные формулы находятся в docs/.')
def footer(c,doc):
 c.setFillColor(colors.HexColor('#24705A'));c.setFont('Text',8);c.drawString(45,28,'Город Хвостиков • MVP 0.1');c.drawRightString(550,28,str(doc.page))
doc=SimpleDocTemplate(str(out/'Город-Хвостиков-документация.pdf'),pagesize=(595,842),rightMargin=45,leftMargin=45,topMargin=45,bottomMargin=48,title='Город Хвостиков — документация MVP',author='Команда проекта')
doc.build(story,onFirstPage=footer,onLaterPages=footer)
